def clean_text(text):
    if text is None:
        return ""
    text = str(text)
    text = text.replace("\xa0", " ")
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", "", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def unique_preserve(items):
    seen = set()
    out = []
    for item in items:
        key = json.dumps(item, ensure_ascii=False, sort_keys=True) if isinstance(item, (dict, list)) else str(item)
        if key in seen:
            continue
        seen.add(key)
        out.append(item)
    return out


def normalize_url(url):
    if not url:
        return None
    url = urljoin(BASE_URL + "/", url)
    parsed = urlparse(url)
    scheme = "https"
    netloc = parsed.netloc.lower()
    if netloc not in ALLOWED_NETLOCS:
        return None
    path = parsed.path or "/"
    qs = []
    for k, v in parse_qsl(parsed.query, keep_blank_values=True):
        if k.lower() in {"id", "nr", "view", "s", "page", "worker", "promotion", "event", "match", "title", "stable", "team", "show"}:
            qs.append((k, v))
    qs.sort(key=lambda x: (x[0], x[1]))
    query = urlencode(qs, doseq=True)
    normalized = urlunparse((scheme, "", path, "", query, ""))
    return normalized


def get_url_params(url):
    parsed = urlparse(url)
    return dict(parse_qsl(parsed.query, keep_blank_values=True))


def classify_url(url):
    params = get_url_params(url)
    sid = params.get("id", "")
    base = SECTION_IDS.get(sid, "general")
    if params.get("nr"):
        if sid == "2":
            return "wrestler_profile"
        if sid == "1":
            return "event_detail"
        if sid == "111":
            return "match_detail"
        if sid == "8":
            return "promotion_detail"
        if sid == "5":
