def allowed_url(url):
    normalized = normalize_url(url)
    if not normalized:
        return False
    params = get_url_params(normalized)
    sid = params.get("id", "")
    return sid in SECTION_IDS


def text_hash(text):
    return hashlib.sha256((text or "").encode("utf-8", errors="ignore")).hexdigest()


def fetch_page(url, retries=FETCH_RETRIES):
    session = get_session()
    for attempt in range(retries):
        try:
            response = session.get(url, timeout=FETCH_TIMEOUT, allow_redirects=True)
            if response.status_code == 200 and response.text:
                return response.url, response.status_code, response.text
        except Exception:
            pass
        time.sleep(min(8.0, 1.5 * (attempt + 1)))
    return url, None, None


def extract_tables(soup):
    tables = []
    for table in soup.find_all("table"):
        headers = []
        header_row = table.find("tr")
        if header_row:
            headers = [clean_text(th.get_text(" ", strip=True)) for th in header_row.find_all(["th", "td"])]
        caption_tag = table.find("caption")
        caption = clean_text(caption_tag.get_text(" ", strip=True)) if caption_tag else ""
        rows = []
        for tr in table.find_all("tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all(["th", "td"])]
            if cells:
                rows.append(cells)
        if headers or rows or caption:
            tables.append({"caption": caption, "headers": headers, "rows": rows})
    return tables


def extract_key_values(soup):
    items = {}
    for table in soup.find_all("table"):
        for tr in table.find_all("tr"):
            cells = tr.find_all(["th", "td"])
            if len(cells) == 2:
                k = clean_text(cells[0].get_text(" ", strip=True)).strip(":")
                v = clean_text(cells[1].get_text(" ", strip=True))
                if k and v and k not in items:
                    items[k] = v
    for dl in soup.find_all("dl"):
        dts = dl.find_all("dt")
        dds = dl.find_all("dd")
        for dt, dd in zip(dts, dds):
            k = clean_text(dt.get_text(" ", strip=True)).strip(":")
            v = clean_text(dd.get_text(" ", strip=True))
            if k and v and k not in items:
                items[k] = v
    for container in soup.find_all(["div", "section", "li", "p"]):
        text = clean_text(container.get_text(" ", strip=True))
        if ":" in text and len(text) < 300:
            left, right = text.split(":", 1)
            k = clean_text(left)
            v = clean_text(right)
            if 1 <= len(k) <= 80 and v and k not in items:
                items[k] = v
    return items


def extract_headings(soup):
    headings = []
    for tag in soup.find_all(["h1", "h2", "h3", "h4"]):
        txt = clean_text(tag.get_text(" ", strip=True))
        if txt:
            headings.append(txt)
    return unique_preserve(headings)


def extract_breadcrumbs(soup):
    crumbs = []
    for nav in soup.find_all(["nav", "div", "ul"]):
        txt = clean_text(nav.get_text(" ", strip=True))
        if "CAGEMATCH" in txt and ">" in txt:
            parts = [clean_text(x) for x in re.split(r">|/", txt) if clean_text(x)]
            if len(parts) >= 2:
                crumbs.extend(parts)
    return unique_preserve(crumbs)


def extract_sections(soup):
    sections = []
    for heading in soup.find_all(["h2", "h3"]):
        title = clean_text(heading.get_text(" ", strip=True))
        if not title:
            continue
        parts = []
        sibling = heading.find_next_sibling()
        depth = 0
        while sibling and getattr(sibling, "name", None) not in {"h2", "h3"} and depth < 12:
            txt = clean_text(sibling.get_text(" ", strip=True))
            if txt:
                parts.append(txt)
            sibling = sibling.find_next_sibling()
            depth += 1
        body = clean_text(" ".join(parts))[:MAX_SECTION_CHARS]
        if body:
            sections.append({"heading": title, "text": body})
    return unique_preserve(sections)


def extract_lists(soup):
    blocks = []
    for ul in soup.find_all(["ul", "ol"]):
        items = []
        for li in ul.find_all("li", recursive=False):
            txt = clean_text(li.get_text(" ", strip=True))
            if txt:
                items.append(txt)
        if items:
            blocks.append(items)
    return unique_preserve(blocks)


def extract_links(soup):
    links = []
    for a in soup.find_all("a", href=True):
        href = normalize_url(a["href"])
        if not href or not allowed_url(href):
            continue
        links.append({
            "url": href,
            "text": clean_text(a.get_text(" ", strip=True))
        })
    return unique_preserve(links)


def extract_meta(soup):
    data = {}
    title_tag = soup.find("title")
    h1 = soup.find("h1")
    if h1:
        data["title"] = clean_text(h1.get_text(" ", strip=True))
    elif title_tag:
        data["title"] = clean_text(title_tag.get_text(" ", strip=True))
    else:
        data["title"] = ""
    desc = soup.find("meta", attrs={"name": re.compile(r"description", re.I)})
    og = soup.find("meta", attrs={"property": re.compile(r"og:description", re.I)})
    if desc:
        data["meta_description"] = clean_text(desc.get("content", ""))
    elif og:
        data["meta_description"] = clean_text(og.get("content", ""))
    else:
        data["meta_description"] = ""
    return data


def extract_body_text(soup):
    for tag in soup(["script", "style", "noscript"]):
        tag.extract()
    body = soup.find("body") or soup
    text = clean_text(body.get_text(" ", strip=True))
    return text[:MAX_BODY_CHARS]


def page_quality_hints(raw):
    hints = {
        "has_title": bool(raw.get("raw_title")),
        "has_body": bool(raw.get("raw_body_snippet")),
        "table_count": len(raw.get("raw_tables", [])),
        "infobox_field_count": len(raw.get("raw_infobox", {})),
        "section_count": len(raw.get("raw_sections", [])),
        "link_count": len(raw.get("raw_links", []))
    }
    score = 0.0
    score += 0.15 if hints["has_title"] else 0.0
    score += 0.15 if hints["has_body"] else 0.0
    score += min(0.25, hints["table_count"] * 0.03)
    score += min(0.20, hints["infobox_field_count"] * 0.02)
    score += min(0.10, hints["section_count"] * 0.02)
    score += min(0.15, hints["link_count"] * 0.005)
    hints["deterministic_quality_score"] = round(min(1.0, score), 3)
    return hints


def extract_page_data(url, status_code, html):
    soup = BeautifulSoup(html, "html.parser")
    meta = extract_meta(soup)
    links = extract_links(soup)
    params = get_url_params(url)
    body_text = extract_body_text(soup)
    raw = {
        "source": "cagematch.net",
