        "url_params": params,
        "crawled_at": now_utc(),
        "raw_title": meta.get("title", ""),
        "raw_subtitles": extract_headings(soup),
        "raw_breadcrumbs": extract_breadcrumbs(soup),
        "raw_meta_description": meta.get("meta_description", ""),
        "raw_infobox": extract_key_values(soup),
        "raw_tables": extract_tables(soup),
        "raw_sections": extract_sections(soup),
        "raw_lists": extract_lists(soup),
        "raw_links": links,
        "raw_body_snippet": body_text,
        "page_fingerprint": text_hash((meta.get("title", "") + "\n" + body_text[:6000]))
    }
    raw["quality_hints"] = page_quality_hints(raw)
    return raw


def extract_json_candidate(text):
    text = (text or "").strip()
    if not text:
        return None
    if text.startswith("```"):
        text = re.sub(r"^```[a-zA-Z0-9_-]*\n?", "", text)
        text = re.sub(r"\n?```$", "", text).strip()
    try:
        return json.loads(text)
    except Exception:
        pass
    start = text.find("{")
    end = text.rfind("}")
    if start != -1 and end != -1 and end > start:
        candidate = text[start:end + 1]
        try:
            return json.loads(candidate)
        except Exception:
            return None
    return None


def build_llm_prompt(raw_data):
    trimmed = dict(raw_data)
    if len(trimmed.get("raw_body_snippet", "")) > 8000:
        trimmed["raw_body_snippet"] = trimmed["raw_body_snippet"][:8000]
    serialized = json.dumps(trimmed, ensure_ascii=False)
    if len(serialized) > LLM_MAX_CHARS:
        serialized = serialized[:LLM_MAX_CHARS]
    prompt = (
        "You extract and normalize professional wrestling data from cagematch.net into high-quality training records. "
        "Return exactly one valid JSON object and nothing else. "
        "Preserve facts, avoid invention, and do not omit tables, dates, names, ratings, titles, relationships, promotions, events, match details, roster data, career data, stables, tag teams, comments-derived factual consensus, and historical context when present. "
        "Use this schema: "
        "{"
        '"type":"string",'
        '"primary_entity":"string",'
        '"summary":"string",'
        '"facts":{},'
        '"relationships":[], '
        '"aliases":[], '
        '"raw_source_url":"string",'
        '"quality_score":0.0'
        "}. "
        "Only include facts that are supported by the input. "
        "Input: " + serialized
    )
    return prompt


def call_llm_clean(raw_data):
    if not LLM_ENABLED:
        return None, "disabled"
    payload = {
        "model": LLM_MODEL,
        "max_tokens": LLM_MAX_TOKENS,
        "temperature": 0.1,
        "messages": [{"role": "user", "content": build_llm_prompt(raw_data)}],
        "top_p": 1,
        "top_k": 40,
        "presence_penalty": 0,
        "frequency_penalty": 0
    }
    try:
        response = requests.post(LLM_URL, json=payload, headers=LLM_HEADERS, timeout=LLM_TIMEOUT)
        if response.status_code != 200:
            return None, f"http_{response.status_code}"
        data = response.json()
        content = data.get("choices", [{}]).get("message", {}).get("content", "")
        parsed = extract_json_candidate(content)
        if parsed is None:
            return None, "invalid_json"
        return parsed, "ok"
    except Exception as e:
        return None, clean_text(str(e))[:200]


def write_jsonl(record):
    line = json.dumps(record, ensure_ascii=False)
    with WRITE_LOCK:
        with open(OUTPUT_FILE, "a", encoding="utf-8") as f:
            f.write(line + "\n")
            f.flush()
            if PAGE_WRITE_FLUSH:
                os.fsync(f.fileno())
        ROW_COUNTER += 1
        if ROW_COUNTER % PRINT_EVERY == 0 or ROW_COUNTER <= 3:
            elapsed = max(0.001, time.time() - START_TIME)
            rate = ROW_COUNTER / elapsed
            print(f"[{datetime.now().strftime('%H:%M:%S')}] Written {ROW_COUNTER} records | {rate:.2f} rows/sec | errors {ERROR_COUNTER}", flush=True)


def load_existing_urls():
    if not os.path.exists(OUTPUT_FILE):
        return
    try:
        with open(OUTPUT_FILE, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                url = normalize_url(obj.get("normalized_url") or obj.get("url") or "")
                if url:
                    VISITED_URLS.add(url)
                    ENQUEUED_URLS.add(url)
                    ROW_COUNTER += 1
    except Exception:
        pass


def enqueue_url(url_queue, url):
    normalized = normalize_url(url)
    if not normalized or not allowed_url(normalized):
        return False
    with ENQUEUED_LOCK:
        if normalized in ENQUEUED_URLS:
            return False
        ENQUEUED_URLS.add(normalized)
    url_queue.put(normalized)
    return True


def maybe_enqueue_pagination(url_queue, raw_data):
    params = raw_data.get("url_params", {})
    sid = params.get("id", "")
    if sid not in SECTION_IDS:
        return
    if params.get("nr"):
        return
    current_s = 0
    try:
        current_s = int(params.get("s", "0") or "0")
    except Exception:
        current_s = 0
    if current_s >= PAGINATION_LIMIT:
        return
    link_count = len(raw_data.get("raw_links", []))
    table_count = len(raw_data.get("raw_tables", []))
    body_len = len(raw_data.get("raw_body_snippet", ""))
    if link_count < 5 and table_count == 0 and body_len < 800:
        return
    next_s = current_s + 100
    next_params = []
    for k, v in sorted(params.items()):
        if k != "s":
            next_params.append((k, v))
    next_params.append(("s", str(next_s)))
    next_url = f"{BASE_URL}/?{urlencode(next_params)}"
    enqueue_url(url_queue, next_url)


def discover_urls(raw_data):
    discovered = []
    for item in raw_data.get("raw_links", []):
        url = item.get("url")
        if url and allowed_url(url):
            discovered.append(url)
    params = raw_data.get("url_params", {})
    sid = params.get("id", "")
    nr = params.get("nr")
    if sid == "28" and nr:
        discovered.append(f"{BASE_URL}/?id=28&nr={nr}&view=matches")
        discovered.append(f"{BASE_URL}/?id=28&nr={nr}&view=titles")
        discovered.append(f"{BASE_URL}/?id=28&nr={nr}&view=matchguide")
        discovered.append(f"{BASE_URL}/?id=28&nr={nr}&view=ratings")
        discovered.append(f"{BASE_URL}/?id=28&nr={nr}&view=comments")
    if sid == "2" and nr:
        discovered.append(f"{BASE_URL}/?id=2&nr={nr}&view=matches")
        discovered.append(f"{BASE_URL}/?id=2&nr={nr}&view=titles")
        discovered.append(f"{BASE_URL}/?id=2&nr={nr}&view=comments")
    if sid == "1" and nr:
        discovered.append(f"{BASE_URL}/?id=1&nr={nr}&view=card")
        discovered.append(f"{BASE_URL}/?id=1&nr={nr}&view=results")
        discovered.append(f"{BASE_URL}/?id=1&nr={nr}&view=comments")
    if sid == "111" and nr:
        discovered.append(f"{BASE_URL}/?id=111&nr={nr}&view=comments")
    return unique_preserve([u for u in discovered if allowed_url(u)])


def process_url(url_queue, url):
    normalized = normalize_url(url)
    if not normalized:
        return
    with VISITED_LOCK:
        if normalized in VISITED_URLS:
            return
        VISITED_URLS.add(normalized)
    final_url, status_code, html = fetch_page(normalized)
    if not html:
        ERROR_COUNTER += 1
        return
    final_url = normalize_url(final_url) or normalized
    raw_data = extract_page_data(final_url, status_code, html)
    signature = raw_data.get("page_fingerprint")
    with SEEN_HTML_LOCK:
        if signature in SEEN_HTML_SIGNATURES:
            return
        SEEN_HTML_SIGNATURES.add(signature)
    cleaned, llm_status = call_llm_clean(raw_data)
    record = {
        "source": "cagematch.net",
        "section_type": raw_data.get("section_type"),
        "section_group": raw_data.get("section_group"),
        "url": final_url,
        "normalized_url": raw_data.get("normalized_url"),
        "url_params": raw_data.get("url_params"),
        "crawled_at": raw_data.get("crawled_at"),
        "http_status": raw_data.get("http_status"),
        "llm_cleaned": cleaned,
        "llm_status": llm_status,
        "raw_title": raw_data.get("raw_title"),
        "raw_subtitles": raw_data.get("raw_subtitles"),
        "raw_breadcrumbs": raw_data.get("raw_breadcrumbs"),
        "raw_meta_description": raw_data.get("raw_meta_description"),
        "raw_tables": raw_data.get("raw_tables"),
        "raw_infobox": raw_data.get("raw_infobox"),
        "raw_sections": raw_data.get("raw_sections"),
        "raw_lists": raw_data.get("raw_lists"),
        "raw_links": raw_data.get("raw_links"),
        "raw_body_snippet": raw_data.get("raw_body_snippet"),
        "page_fingerprint": raw_data.get("page_fingerprint"),
        "quality_hints": raw_data.get("quality_hints")
    }
    write_jsonl(record)
    maybe_enqueue_pagination(url_queue, raw_data)
    for discovered in discover_urls(raw_data):
        enqueue_url(url_queue, discovered)
    time.sleep(random.uniform(RANDOM_DELAY_MIN, RANDOM_DELAY_MAX))


def worker_func(url_queue):
    while True:
        try:
            url = url_queue.get(timeout=15)
        except Empty:
