def worker_func(url_queue):
    while True:
        try:
            url = url_queue.get(timeout=15)
        except Empty:
            return
        try:
            process_url(url_queue, url)
        except Exception:
            ERROR_COUNTER += 1
        finally:
            url_queue.task_done()


def build_start_urls():
    urls = []
    for target in CRAWL_TARGETS:
        sid = target["id"]
        view = target["view"]
        if view:
            urls.append(BASE_URL + "/?id=" + sid + "&view=" + view + "&s=0")
        else:
            urls.append(BASE_URL + "/?id=" + sid + "&s=0")
    if DETAIL_SWEEP > 0:
        for sid in ["2", "1", "111", "8", "5", "28", "29", "93", "87", "91"]:
            for nr in range(1, DETAIL_SWEEP + 1):
                urls.append(BASE_URL + "/?id=" + sid + "&nr=" + str(nr))
    return unique_preserve([u for u in urls if allowed_url(u)])


def main():
    print("Starting Cagematch dataset crawler", flush=True)
    print("Output: " + OUTPUT_FILE, flush=True)
    print("Workers: " + str(MAX_WORKERS), flush=True)
    print("LLM enabled: " + str(LLM_ENABLED), flush=True)
    if not os.path.exists(OUTPUT_FILE):
        with open(OUTPUT_FILE, "w", encoding="utf-8"):
            pass
    load_existing_urls()
    START_TIME = time.time()
    start_urls = build_start_urls()
    random.shuffle(start_urls)
    url_queue = Queue()
    added = 0
    for url in start_urls:
        if enqueue_url(url_queue, url):
            added += 1
    print("Queued " + str(added) + " fresh seed URLs", flush=True)
    threads = []
    for _ in range(MAX_WORKERS):
        t = threading.Thread(target=worker_func, args=(url_queue,), daemon=True)
        t.start()
        threads.append(t)
    try:
        url_queue.join()
    except KeyboardInterrupt:
        print("Stopped by user", flush=True)
    elapsed = max(0.001, time.time() - START_TIME)
    count = ROW_COUNTER
    print("Done. Total records written: " + str(count), flush=True)
    print("Errors: " + str(ERROR_COUNTER), flush=True)
    print("Elapsed seconds: " + str(round(elapsed, 2)), flush=True)
    print("Average rows/sec: " + str(round(count / elapsed, 2)), flush=True)


if __name__ == "__main__":
